  "svc.4d5dSim": { en: "4D/5D Simulation", hi: "4D/5D सिमुलेशन", ar: "محاكاة 4D/5D", fr: "Simulation 4D/5D", de: "4D/5D-Simulation", es: "Simulación 4D/5D", zh: "4D/5D模拟", ja: "4D/5Dシミュレーション" },
  "svc.4d5dSimDesc": { en: "Construction sequencing and cost estimation integrated with BIM.", hi: "BIM के साथ एकीकृत निर्माण अनुक्रमण और लागत अनुमान।", ar: "تسلسل البناء وتقدير التكلفة المدمج مع BIM.", fr: "Séquençage de construction et estimation des coûts intégrés au BIM.", de: "Bausequenzierung und Kostenermittlung integriert in BIM.", es: "Secuenciación de construcción y estimación de costos integrada con BIM.", zh: "与BIM集成的施工排序和成本估算。", ja: "BIMと統合された施工シーケンスとコスト見積もり。" },
  "svc.bimConsulting": { en: "BIM Consulting", hi: "BIM परामर्श", ar: "استشارات BIM", fr: "Conseil BIM", de: "BIM-Beratung", es: "Consultoría BIM", zh: "BIM咨询", ja: "BIMコンサルティング" },
  "svc.bimConsultingDesc": { en: "BIM execution plans, standards, and digital transformation strategy.", hi: "BIM निष्पादन योजनाएँ, मानक और डिजिटल परिवर्तन रणनीति।", ar: "خطط تنفيذ BIM والمعايير واستراتيجية التحول الرقمي.", fr: "Plans d'exécution BIM, normes et stratégie de transformation numérique.", de: "BIM-Ausführungspläne, Standards und Strategie zur digitalen Transformation.", es: "Planes de ejecución BIM, estándares y estrategia de transformación digital.", zh: "BIM执行计划、标准和数字化转型战略。", ja: "BIM実行計画、標準、デジタルトランスフォーメーション戦略。" },
  "svc.digitalTwin": { en: "Digital Twin", hi: "डिजिटल ट्विन", ar: "التوأم الرقمي", fr: "Jumeau numérique", de: "Digitaler Zwilling", es: "Gemelo digital", zh: "数字孪生", ja: "デジタルツイン" },
  "svc.digitalTwinDesc": { en: "Real-time digital replicas for facility management and operations.", hi: "सुविधा प्रबंधन और संचालन के लिए वास्तविक समय डिजिटल प्रतिकृतियां।", ar: "نسخ رقمية في الوقت الفعلي لإدارة المرافق والعمليات.", fr: "Répliques numériques en temps réel pour la gestion et l'exploitation des installations.", de: "Echtzeit-Digitalreplikate für Facility Management und Betrieb.", es: "Réplicas digitales en tiempo real para gestión y operaciones de instalaciones.", zh: "用于设施管理和运营的实时数字复制品。", ja: "施設管理と運用のためのリアルタイムデジタルレプリカ。" },

