  "process.discoveryDesc": { en: "Understand project scope, standards, and deliverables", hi: "प्रोजेक्ट स्कोप, मानक और डिलीवरेबल्स को समझें", ar: "فهم نطاق المشروع والمعايير والمخرجات", fr: "Comprendre la portée, les normes et les livrables", de: "Projektumfang, Standards und Liefergegenstände verstehen", es: "Comprender el alcance, estándares y entregables", zh: "了解项目范围、标准和交付成果", ja: "プロジェクト範囲、基準、成果物の理解" },
