  "process.modelingDesc": { en: "Multi-discipline BIM modeling across all LODs", hi: "सभी LODs में बहु-विषय BIM मॉडलिंग", ar: "نمذجة BIM متعددة التخصصات عبر جميع مستويات التطوير", fr: "Modélisation BIM multidisciplinaire à tous les niveaux de détail", de: "Multidisziplinäre BIM-Modellierung über alle LODs", es: "Modelado BIM multidisciplinario en todos los LODs", zh: "跨所有LOD的多专业BIM建模", ja: "全LODにわたるマルチディシプリンBIMモデリング" },
