  "process.deliveryDesc": { en: "Final QA/QC, documentation, and handover", hi: "अंतिम QA/QC, दस्तावेज़ीकरण और हैंडओवर", ar: "ضمان الجودة النهائي والتوثيق والتسليم", fr: "QA/QC final, documentation et remise", de: "Abschließende QA/QC, Dokumentation und Übergabe", es: "QA/QC final, documentación y entrega", zh: "最终QA/QC、文档和移交", ja: "最終QA/QC、ドキュメンテーション、引渡し" },
