  // ==================== ABOUT ====================
  "about.badge": { en: "About Us", hi: "हमारे बारे में", ar: "من نحن", fr: "À propos de nous", de: "Über uns", es: "Sobre nosotros", zh: "关于我们", ja: "会社概要" },
  "about.title": { en: "Engineering the", hi: "इंजीनियरिंग", ar: "هندسة", fr: "Concevoir le", de: "Gestaltung der", es: "Diseñando el", zh: "设计建筑的", ja: "建設の" },
  "about.titleHighlight": { en: "Digital Future", hi: "डिजिटल भविष्य", ar: "المستقبل الرقمي", fr: "Futur Numérique", de: "Digitalen Zukunft", es: "Futuro Digital", zh: "数字未来", ja: "デジタルな未来を" },
  "about.titleEnd": { en: "of Construction", hi: "निर्माण का", ar: "للبناء", fr: "de la Construction", de: "des Bauens", es: "de la Construcción", zh: "", ja: "エンジニアリング" },
  "about.desc": { en: "WASI Digital Engineering is a leading BIM and digital engineering consultancy transforming the AEC industry through technology, expertise, and innovation.", hi: "WASI डिजिटल इंजीनियरिंग एक अग्रणी BIM और डिजिटल इंजीनियरिंग परामर्श है जो प्रौद्योगिकी, विशेषज्ञता और नवाचार के माध्यम से AEC उद्योग को बदल रही है।", ar: "WASI للهندسة الرقمية هي شركة استشارية رائدة في BIM والهندسة الرقمية تحول صناعة AEC من خلال التكنولوجيا والخبرة والابتكار.", fr: "WASI Digital Engineering est un cabinet de conseil BIM et d'ingénierie numérique de premier plan transformant l'industrie AEC par la technologie, l'expertise et l'innovation.", de: "WASI Digital Engineering ist eine führende BIM- und Digitalberatung, die die AEC-Branche durch Technologie, Expertise und Innovation transformiert.", es: "WASI Digital Engineering es una consultora líder en BIM e ingeniería digital que transforma la industria AEC a través de tecnología, experiencia e innovación.", zh: "WASI数字工程是领先的BIM和数字工程咨询公司，通过技术、专业知识和创新改变AEC行业。", ja: "WASIデジタルエンジニアリングは、テクノロジー、専門知識、イノベーションを通じてAEC業界を変革するBIMおよびデジタルエンジニアリングコンサルタントです。" },
  "about.ourStory": { en: "Our Story", hi: "हमारी कहानी", ar: "قصتنا", fr: "Notre histoire", de: "Unsere Geschichte", es: "Nuestra historia", zh: "我们的故事", ja: "私たちの物語" },
  "about.valuesLabel": { en: "Our Values", hi: "हमारे मूल्य", ar: "قيمنا", fr: "Nos valeurs", de: "Unsere Werte", es: "Nuestros valores", zh: "我们的价值观", ja: "私たちの価値観" },
  "about.valuesTitle": { en: "What Drives Us", hi: "क्या हमें प्रेरित करता है", ar: "ما يحركنا", fr: "Ce qui nous motive", de: "Was uns antreibt", es: "Lo que nos impulsa", zh: "驱动我们的力量", ja: "私たちの原動力" },
