  "careers.titleEnd": { en: "with Us", hi: "हमारे साथ बनाएँ", ar: "معنا", fr: "avec Nous", de: "mit Uns", es: "con Nosotros", zh: "与我们一起", ja: "私たちと共に" },
  "careers.desc": { en: "Join a team of 150+ passionate engineers and architects shaping the future of digital construction. We're always looking for exceptional talent.", hi: "150+ उत्साही इंजीनियरों और आर्किटेक्ट्स की टीम में शामिल हों जो डिजिटल निर्माण के भविष्य को आकार दे रहे हैं।", ar: "انضم إلى فريق يضم أكثر من 150 مهندساً ومعمارياً شغوفاً يشكلون مستقبل البناء الرقمي.", fr: "Rejoignez une équipe de plus de 150 ingénieurs et architectes passionnés qui façonnent l'avenir de la construction numérique.", de: "Werden Sie Teil eines Teams von über 150 leidenschaftlichen Ingenieuren und Architekten, die die Zukunft des digitalen Bauens gestalten.", es: "Únase a un equipo de más de 150 ingenieros y arquitectos apasionados que están dando forma al futuro de la construcción digital.", zh: "加入150多位充满激情的工程师和建筑师团队，共同塑造数字建筑的未来。", ja: "デジタル建設の未来を形作る150名以上のエンジニアとアーキテクトのチームに参加してください。" },
