  "careers.openPositionsDesc": { en: "Find the role that fits your expertise.", hi: "अपनी विशेषज्ञता के अनुकूल भूमिका खोजें।", ar: "ابحث عن الدور الذي يناسب خبرتك.", fr: "Trouvez le rôle qui correspond à votre expertise.", de: "Finden Sie die Rolle, die zu Ihrer Expertise passt.", es: "Encuentre el rol que se ajuste a su experiencia.", zh: "找到适合您专业知识的角色。", ja: "あなたの専門知識に合った役割を見つけてください。" },
