  "careers.noMatchDesc": { en: "Send us your resume and we'll reach out when the right opportunity opens.", hi: "हमें अपना रिज्यूमे भेजें और सही अवसर आने पर हम संपर्क करेंगे।", ar: "أرسل لنا سيرتك الذاتية وسنتواصل معك عندما تتوفر الفرصة المناسبة.", fr: "Envoyez-nous votre CV et nous vous contacterons dès qu'une opportunité se présente.", de: "Senden Sie uns Ihren Lebenslauf und wir melden uns, wenn sich die richtige Möglichkeit ergibt.", es: "Envíenos su currículum y nos pondremos en contacto cuando surja la oportunidad adecuada.", zh: "发送您的简历，当有合适的机会时我们会联系您。", ja: "履歴書をお送りください。適切な機会が見つかり次第ご連絡いたします。" },
  "careers.submitResume": { en: "Submit Your Resume", hi: "अपना रिज्यूमे जमा करें", ar: "أرسل سيرتك الذاتية", fr: "Soumettre votre CV", de: "Lebenslauf einreichen", es: "Enviar su currículum", zh: "提交简历", ja: "履歴書を送信" },

